#include "tmd_codec3d.h"
#include <stdio.h>

#ifndef TMD_TO_OBJ_MAX_FILE
#define TMD_TO_OBJ_MAX_FILE (4UL * 1024UL * 1024UL)
#endif
#ifndef TMD_TO_OBJ_MAX_OBJECTS
#define TMD_TO_OBJ_MAX_OBJECTS 256UL
#endif
#ifndef TMD_TO_OBJ_MAX_FACES
#define TMD_TO_OBJ_MAX_FACES 65536UL
#endif

static unsigned char g_file[TMD_TO_OBJ_MAX_FILE];
static TMD_Object g_objects[TMD_TO_OBJ_MAX_OBJECTS];
static TMD_Face g_faces[TMD_TO_OBJ_MAX_FACES];

static int load_file(const char *path, unsigned char *buf, unsigned long cap, unsigned long *out_size)
{
    FILE *f;
    unsigned long n;
    int c;
    f = fopen(path, "rb");
    if (f == 0) return 0;
    n = 0UL;
    while ((c = fgetc(f)) != EOF) {
        if (n >= cap) { fclose(f); return 0; }
        buf[n++] = (unsigned char)c;
    }
    fclose(f);
    *out_size = n;
    return 1;
}

int main(int argc, char **argv)
{
    TMD_Context ctx;
    FILE *out;
    unsigned long size;
    tmd_u32 obji;
    tmd_u32 base_index;
    int r;

    if (argc < 3) {
        printf("usage: tmd_to_obj input.tmd output.obj\n");
        return 2;
    }
    if (!load_file(argv[1], g_file, TMD_TO_OBJ_MAX_FILE, &size)) {
        printf("could not load input; max static buffer is %lu bytes\n", (unsigned long)TMD_TO_OBJ_MAX_FILE);
        return 1;
    }
    r = tmd_parse(&ctx, g_file, (tmd_u32)size, g_objects, TMD_TO_OBJ_MAX_OBJECTS);
    if (r != TMD_ERR_OK) {
        printf("parse error: %s (%d)\n", tmd_result_string(r), r);
        return 1;
    }

    out = fopen(argv[2], "w");
    if (out == 0) {
        printf("could not create output OBJ\n");
        return 1;
    }

    fprintf(out, "# generated by psx_tmd_codec3d_c89; integer coordinates, no heap, no floats\n");
    fprintf(out, "# source objects: %lu\n", (unsigned long)ctx.parsed_object_count);

    base_index = 1UL;
    for (obji = 0UL; obji < ctx.parsed_object_count; ++obji) {
        TMD_Object *o;
        tmd_u32 vi;
        tmd_u32 written;
        tmd_u32 needed;
        tmd_u32 unsupported;
        tmd_u32 fi;
        o = ctx.objects + obji;
        fprintf(out, "o tmd_object_%lu\n", (unsigned long)obji);
        for (vi = 0UL; vi < o->n_vert; ++vi) {
            TMD_Vertex v;
            r = tmd_get_vertex(&ctx, obji, vi, &v);
            if (r != TMD_ERR_OK) { fclose(out); return 1; }
            fprintf(out, "v %ld %ld %ld\n", (long)v.x, (long)v.y, (long)v.z);
        }
        r = tmd_decode_object_faces(&ctx, obji, g_faces, TMD_TO_OBJ_MAX_FACES, &written, &needed, &unsupported);
        if (r != TMD_ERR_OK && r != TMD_ERR_OUTPUT_OVERFLOW) {
            fprintf(out, "# object %lu face decode error: %s\n", (unsigned long)obji, tmd_result_string(r));
            base_index += o->n_vert;
            continue;
        }
        for (fi = 0UL; fi < written; ++fi) {
            TMD_Face *f;
            f = g_faces + fi;
            if (f->vertex_count == TMD_FACE_TRIANGLE) {
                fprintf(out, "f %lu %lu %lu\n",
                        (unsigned long)(base_index + f->v[0]),
                        (unsigned long)(base_index + f->v[1]),
                        (unsigned long)(base_index + f->v[2]));
            } else if (f->vertex_count == TMD_FACE_QUAD) {
                fprintf(out, "f %lu %lu %lu %lu\n",
                        (unsigned long)(base_index + f->v[0]),
                        (unsigned long)(base_index + f->v[1]),
                        (unsigned long)(base_index + f->v[2]),
                        (unsigned long)(base_index + f->v[3]));
            }
        }
        if (unsupported != 0UL) fprintf(out, "# unsupported non-polygon primitives: %lu\n", (unsigned long)unsupported);
        if (needed > written) fprintf(out, "# output face buffer truncated: needed %lu\n", (unsigned long)needed);
        base_index += o->n_vert;
    }

    fclose(out);
    return 0;
}
